import React, { useState } from 'react'
import { Link } from 'react-router-dom'

function Navigation() {
  const [isMenuOpen, setIsMenuOpen] = useState(false)

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen)
  }

  return (
    <nav className="site-nav" aria-label="Main navigation">
      <Link to="/" className="nav-brand">Aaron Diefes</Link>
      <button
        className="menu-toggle"
        aria-expanded={isMenuOpen}
        aria-controls="nav-menu"
        onClick={toggleMenu}
      >
        <span className="sr-only">Toggle menu</span>
        <span className="hamburger-icon"></span>
      </button>
      <ul id="nav-menu" className="nav-links" hidden={!isMenuOpen}>
        <li><Link to="/">Home</Link></li>
        <li><Link to="/projects/cpu-simulator">CPU Simulator</Link></li>
        <li><Link to="/projects/graphics-engine/wasm">Graphics Engine</Link></li>
        <li><Link to="/docs">Documentation</Link></li>
        <li><a href="https://github.com/AaronDiefes" target="_blank" rel="noopener noreferrer">GitHub</a></li>
      </ul>
    </nav>
  )
}

export default Navigation

