import React, { useState, useEffect } from 'react'
import { useAnimationEngine } from '../hooks/useAnimationEngine'
import CPUVisualizer from '../components/cpu/CPUVisualizer'
import ControlPanel from '../components/cpu/ControlPanel'
import ProgramSelector from '../components/cpu/ProgramSelector'
import InstructionList from '../components/cpu/InstructionList'

/**
 * CPU Simulator Page - Main page component
 * Loads programs, manages animation engine, and coordinates UI
 */
function CPUSimulatorPage() {
  const { currentState, isPlaying, progress, controls } = useAnimationEngine()
  const [programs, setPrograms] = useState([])
  const [currentProgram, setCurrentProgram] = useState(null)

  // Load available programs on mount
  useEffect(() => {
    // Import program modules
    Promise.all([
      import('../lib/cpu/programs/basic-instructions.js'),
      import('../lib/cpu/programs/fibonacci.js'),
      import('../lib/cpu/core/sequence-generator.js')
    ]).then(() => {
      if (window.PROGRAMS) {
        const programList = Object.keys(window.PROGRAMS).map(key => ({
          id: key,
          name: window.PROGRAMS[key].name || key,
          program: window.PROGRAMS[key]
        }))
        setPrograms(programList)

        // Load first program by default
        if (programList.length > 0) {
          loadProgram(programList[0].id)
        }
      }
    })
  }, [])

  const loadProgram = (programId) => {
    if (!window.SequenceGenerator || !window.PROGRAMS) return

    const program = window.PROGRAMS[programId]
    if (!program) return

    // Generate animation frames
    const generator = new window.SequenceGenerator()
    const frames = generator.generateSequence(program)

    controls.loadFrames(frames)
    setCurrentProgram(program)
  }

  const handleProgramChange = (programId) => {
    loadProgram(programId)
  }

  return (
    <>
      <style>{`
        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }

        body {
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
          background: linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%);
          color: #333;
          min-height: 100vh;
          padding: 2rem;
        }

        .cpu-simulator-page {
          max-width: 1400px;
          margin: 0 auto;
          background: white;
          border-radius: 12px;
          box-shadow: 0 20px 60px rgba(0,0,0,0.3);
          overflow: hidden;
        }

        .page-header {
          background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
          color: white;
          padding: 2rem;
          text-align: center;
        }

        .page-header h1 {
          margin-bottom: 0.5rem;
        }

        .page-header p {
          opacity: 0.9;
          font-size: 1.1rem;
        }

        .demo-layout {
          display: grid;
          grid-template-columns: 300px 1fr;
          gap: 2rem;
          padding: 2rem;
        }

        .sidebar {
          background: #f8f9fa;
          padding: 1.5rem;
          border-radius: 8px;
          overflow-y: auto;
          max-height: calc(100vh - 200px);
        }

        .visualization-area {
          padding: 1.5rem;
          min-width: 0;
        }

        .control-panel {
          margin-bottom: 1.5rem;
          padding: 1rem;
          background: white;
          border-radius: 8px;
          border: 1px solid #e0e0e0;
        }

        .playback-controls {
          display: flex;
          gap: 0.5rem;
          margin-bottom: 1rem;
        }

        .control-btn {
          flex: 1;
          padding: 0.75rem;
          background: #f0f0f0;
          border: 1px solid #ddd;
          border-radius: 6px;
          cursor: pointer;
          font-weight: 500;
          transition: all 0.2s;
        }

        .control-btn:hover {
          background: #e0e0e0;
        }

        .control-btn.primary {
          background: #2E7D32;
          color: white;
          border-color: #1B5E20;
        }

        .control-btn.primary:hover {
          background: #1B5E20;
        }

        .progress-info {
          text-align: center;
          margin-bottom: 1rem;
          font-size: 0.9rem;
          color: #666;
        }

        .speed-controls {
          display: flex;
          gap: 0.5rem;
          align-items: center;
        }

        .speed-controls label {
          font-weight: 500;
          margin-right: 0.5rem;
        }

        .speed-btn {
          flex: 1;
          padding: 0.5rem;
          background: white;
          border: 1px solid #ddd;
          border-radius: 4px;
          cursor: pointer;
          font-size: 0.85rem;
        }

        .speed-btn:hover {
          background: #f0f0f0;
        }

        .program-selector {
          margin-bottom: 1.5rem;
          padding: 1rem;
          background: white;
          border-radius: 8px;
          border: 1px solid #e0e0e0;
        }

        .program-selector label {
          display: block;
          font-weight: 600;
          margin-bottom: 0.5rem;
          color: #2c3e50;
        }

        .program-selector select {
          width: 100%;
          padding: 0.5rem;
          border: 1px solid #ddd;
          border-radius: 4px;
          font-size: 1rem;
        }

        .instruction-list {
          padding: 1rem;
          background: white;
          border-radius: 8px;
          border: 1px solid #e0e0e0;
        }

        .instruction-list h3 {
          margin-bottom: 1rem;
          color: #2c3e50;
        }

        .instruction-list ol {
          list-style-position: inside;
        }

        .instruction-list li {
          padding: 0.5rem;
          margin-bottom: 0.25rem;
          border-radius: 4px;
          transition: background 0.2s;
        }

        .instruction-list li:hover {
          background: #f0f0f0;
        }

        .instruction-list li.active {
          background: #fff3cd;
          font-weight: 600;
        }

        @media (max-width: 1024px) {
          .demo-layout {
            grid-template-columns: 1fr;
          }

          .sidebar {
            max-height: none;
          }
        }
      `}</style>

      <div className="cpu-simulator-page">
        <header className="page-header">
          <h1>CPU Pipeline Simulator</h1>
          <p>Interactive visualization of MIPS instruction execution with 5-stage pipeline</p>
        </header>

        <div className="demo-layout">
          <aside className="sidebar">
            <ProgramSelector programs={programs} onProgramChange={handleProgramChange} />
            <ControlPanel controls={controls} isPlaying={isPlaying} progress={progress} />
            <InstructionList
              instructions={currentProgram?.instructions}
              currentFrame={progress.current}
              onJumpToFrame={controls.jumpToFrame}
            />
          </aside>

          <div className="visualization-area">
            <CPUVisualizer state={currentState} />
          </div>
        </div>
      </div>
    </>
  )
}

export default CPUSimulatorPage

